local GameListener = {}

---@private
function GameListener:init()
    LogUtil.logInfo("GameListener:init()")
    CEvents.GameActionTriggerEvent:registerCallBack(self.onGameActionTrigger)
    CEvents.CreativeAddItemEvent:registerCallBack(self.onCreativeAddItemEvent)
    CEvents.ShowRealTimeRank:registerCallBack(self.onShowRealTimeRank)
    CEvents.PlayerMoveEvent:registerCallBack(self.onPlayerMove)
    CEvents.PlayerJumpEvent:registerCallBack(self.onPlayerJump)
    CEvents.PlayerPlayBaseActionEvent:registerCallBack(function(entityPlayer, _, skillProxy)
        local player = PlayerManager:getPlayerByUserId(entityPlayer:getPlatformUserId())
        if not player then
            return
        end
        if player:getBaseAction() then
            skillProxy.value = player:getBaseAction()
        end
    end)

    CEvents.PlayerPlayUpperActionEvent:registerCallBack(function(entityPlayer, _, skillProxy)
        local player = PlayerManager:getPlayerByUserId(entityPlayer:getPlatformUserId())
        if not player then
            return
        end
        if player:getUpperAction() then
            skillProxy.value = player:getUpperAction()
        end
    end)

    BaseListener.registerCallBack(CEvents.GameReadyEvent, self.onGameReady)

    CEvents.LuaPlayerDeathEvent:registerCallBack(self.onPlayerDeath)
end

function GameListener.onCreativeAddItemEvent(itemId, itemCount, meta)
    PlayerManager:getClientPlayer():sendPacket({
        pid = "CreativeAddItem",
        data = { id = itemId, meta = meta or 0, count = itemCount }
    })
end

function GameListener.onShowRealTimeRank(needShow)
    local customGame = T(Global, "customGame")
    needShow.value = customGame:needShowRealTimeRank()
end

function GameListener.onGameActionTrigger(type, param)
    LogUtil.logInfo("GameListener.onGameActionTrigger() type:" .. tostring(type) .. " param:" .. StringUtil.v2s(param))
    if type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_SETTING then
        local data = json.decode(param)
        PlayerManager:getClientPlayer():sendPacket({
            pid = "updateCustomRoomSetting",
            data = data.settingList
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_SAVE then
        ---todo:保存地图
        local customGame = T(Global, "customGame")
        if customGame.ugcExtraConfig and customGame.ugcExtraConfig.isOldSo then
            local data = {}
            data.code = 100
            data.innerCode = Define.RunningConfigErrorCode.OtherError2
            data.msg = Lang:getString("gui_app_update_tip")
            HostApi.sendMsg(0, 0, data.msg)
            UIHelper.showToast(data.msg, 3000)
            ClientHelper.onAppActionTrigger(Define.GameToAppEvent.GAME_ACTION_CUSTOM_ROOM_SAVE_MAP_RESULT, json.encode(data))
            return
        end

        local data = {}
        if not param or param == "" then 
            data.iconUrl = nil
            data.exitGame = true
            data.mapId = nil
            data.mapName = nil
            data.version = 1
        else
            data = json.decode(param)
            data.version = 2
        end
        PlayerManager:getClientPlayer():sendPacket({
            pid = "onCustomRoomSaveMap",
            data = data
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_DISABLE_CHAT then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "onCustomRoomDisableChat",
            data = json.decode(param)
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_KICK_OUT then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "onCustomRoomKickOut",
            id = json.decode(param)
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_SYNC_CUSTOM_ROOM_SETTING then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "syncCustomRoomSetting"
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_SYNC_CUSTOM_ROOM_DISABLE_CHAT then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "syncCustomRoomDisableChat"
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_UPDATE_GLOBAL_PERM_SETTING then
        --自定义房间更新房间全局权限 APP调用引擎
        PlayerManager:getClientPlayer():sendPacket({
            pid = "updateGlobalPermSetting",
            data = json.decode(param).settingList
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_REQUEST_ALL_PLAYER_PERM_SETTING then
        --自定义房间请求获取当前所有玩家权限信息 app调用引擎
        PlayerManager:getClientPlayer():sendPacket({
            pid = "requestAllPlayerPermSetting",
        })
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_UPDATE_PLAYER_PERM_SETTING then
        --自定义房间更新房间某个玩家权限设置 --app调用引擎
        PlayerManager:getClientPlayer():sendPacket({
            pid = "updateUserPermissionSetting",
            data = json.decode(param)
        })

    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_EXCHANGE_OWNER then
        --自定义房间房主转移 --app调用引擎
        PlayerManager:getClientPlayer():sendPacket({
            pid = "exchangeOwner",
            data = tonumber(param)
        })

    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_USER_ENTER then
        --通知服务器当前app界面版本--app调用引擎
        print("GAME_ACTION_CUSTOM_ROOM_USER_ENTER")
        PlayerManager:getClientPlayer():sendPacket({
            pid = "customGameUserVersion",
            data = tonumber(param)
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_CLOSE_GAME then
        --自定义房间ios关闭游戏接口
        CGame.Instance():exitGame("normal")
    elseif type == CDefine.GameActionType.GAME_ACTION_CUSTOM_ROOM_TAKE_PICTURE then
        if param == "start" then
            GUIManager:hideWindowByName("PlayerInventory.json")
            GUIManager:hideWindowByName("Menu.json")
            GUIManager:hideWindowByName("Chat.json")
            RootGuiLayout.Instance():showMainControl()
            --自定义房间打开拍照
            UIHelper.showGameGUILayout("GUITakePictureMain")
            local player = PlayerManager:getClientPlayer()
            player:sendPacket({
                pid = "takePictureStatus",
                userId = player.userId,
                status = true
            })
        elseif param == "end" then
            UIHelper.hideGameGUILayout("GUITakePictureMain")
            local player = PlayerManager:getClientPlayer()
            player:sendPacket({
                pid = "takePictureStatus",
                userId = player.userId,
                status = false
            })
        end
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_GET_GAME_SETTING then
        --自定义房间UGC获取设置配置信息 app调用引擎
        PlayerManager:getClientPlayer():sendPacket({
            pid = "customGameAskingGameSetting",
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_EDIT_GAME_SETTING then
        --自定义房间UGC更新设置配置信息 app调用引擎
        local data = json.decode(param)
        local configMgr = require "base.config.UGCPVPConfigMgr"
        configMgr:unloadOptionConfigLang(data)
        configMgr:unloadComponentField(data)
        configMgr:unLoadOptionItemConfig(data)
        configMgr:unLoadOptionTeamColorConfig(data)
        PlayerManager:getClientPlayer():sendPacket({
            pid = "customGameTryEditGameSetting",
            data = data
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_SET_TEAM_POS then
        local data = json.decode(param);
        data.teamId = math.min(12, math.max(data.teamId, 1))
        data.type = Define.SelectTeam.Position
        GUIManager:hideWindowByName("PlayerInventory.json")
        GUIManager:hideWindowByName("Menu.json")
        GUIManager:hideWindowByName("Chat.json")
        RootGuiLayout.Instance():showMainControl()
        UIHelper.showGameGUILayout("GUISelectTeam", data.type, data.teamId)
        PlayerManager:getClientPlayer():sendPacket({
            pid = "selectTeamStatus",
            data = data
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_SET_TEAM_MARKER then
        local data = json.decode(param);
        data.teamId = math.min(12, math.max(data.teamId, 1))
        data.type = Define.SelectTeam.Marker
        GUIManager:hideWindowByName("PlayerInventory.json")
        GUIManager:hideWindowByName("Menu.json")
        GUIManager:hideWindowByName("Chat.json")
        RootGuiLayout.Instance():showMainControl()
        UIHelper.showGameGUILayout("GUISelectTeam", data.type, data.teamId)
        PlayerManager:getClientPlayer():sendPacket({
            pid = "selectTeamStatus",
            data = data
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_CR_TEAM_MARKER then
        PlayerManager:getClientPlayer():sendPacket({
            pid = "crTeamMarker"
        })
    elseif type == Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_TELEPORT then
        local data = json.decode(param);
        PlayerManager:getClientPlayer():sendPacket({
            pid = "customGameTeleport",
            data = data
        })
    end
end

function GameListener.onGameReady()
    UIHelper.showGameGUILayout("GUICustomGameMain")
    UIHelper.showGameGUILayout("GUICustomGameToolBar")

    ClientHelper.onAppActionTrigger(CDefine.AppActionType.APP_ACTION_GAME_READY)
    local window = GUIManager:getWindowByName("Menu-Radio-Exit", GUIType.RadioButton)
    if window then
        window:removeAllEvents()
        window:registerEvent(GUIEvent.RadioStateChanged, function()
            if window:IsSelected() then
                ClientHelper.onAppActionTrigger(CDefine.AppActionType.APP_ACTION_CUSTOM_ROOM_EXIT_GAME)
                -- CEvents.GameActionTriggerEvent:invoke(Define.AppToGameEvent.GAME_ACTION_CUSTOM_ROOM_CLOSE_GAME)
                window:SetSelected(false)
            end
        end)
    end

    local rankBtn = GUIManager:getWindowByName("ToolBar-Real-Time-Rank-Btn", GUIType.Button)
    if rankBtn then
        rankBtn:SetHorizontalAlignment(HorizontalAlignment.Right)
        rankBtn:SetXPosition({ -0.195, 0 })
    end

    local rank = GUIManager:getWindowByName("RealTimeRank", GUIType.Layout)
    if rank then
        rank:SetHorizontalAlignment(HorizontalAlignment.Right)
    end
    local rank3 = GUIManager:getWindowByName("RealTimeRank-Three-Rank", GUIType.Layout)
    if rank3 then
        rank3:SetHorizontalAlignment(HorizontalAlignment.Right)
    end
    local rank4 = GUIManager:getWindowByName("RealTimeRank-Four-Rank", GUIType.Layout)
    if rank4 then
        rank4:SetHorizontalAlignment(HorizontalAlignment.Right)
    end
    local rank5 = GUIManager:getWindowByName("RealTimeRank-Five-Rank", GUIType.Layout)
    if rank5 then
        rank5:SetHorizontalAlignment(HorizontalAlignment.Right)
    end

    ---获得道具UIBg修改
    local llBuyGoods = GUIManager:getWindowByName("BuyGoodsTip-Bg", GUIType.StaticImage)
    llBuyGoods:SetImage("set:shop.json image:img_9_hint")
    llBuyGoods:SetArea({ 0, 0 }, { 0, 0 }, { 0, 511 }, { 0, 117 })
end

function GameListener.onPlayerMove(player, position)
    local userId = player:getPlatformUserId()
    local _player = PlayerManager:getPlayerByUserId(userId)
    if not _player then
        return
    end
    if not _player.isSleeping or not _player.isCameraLocked then
        return
    end
    if _player.sleepPos and VectorUtil.distanceXZ(_player.sleepPos, position) < 0.5 then
        return
    end
    _player.isSleeping = false
    _player:setBaseAction(nil)
    _player:setUpperAction(nil)
    if _player.Player then
        _player.Player:setBaseAction(0)
        _player.Player:setUpperAction(0)
        _player.Player:setCameraLocked(false)
        _player.isCameraLocked = false
    end
    if Game:getPlatformUserId() == _player.userId then
        _player:sendPacket({
            pid = "cancelSleep"
        })
    end
end

function GameListener.onPlayerJump(platformUserId)
    local player = PlayerManager:getPlayerByUserId(platformUserId)
    if not player.isSleeping or not player.isCameraLocked then
        return
    end
    if player then
        player.isSleeping = false
        player:setBaseAction(nil)
        player:setUpperAction(nil)
        if player.Player then
            player.Player:setBaseAction(0)
            player.Player:setUpperAction(0)
            player.Player:setCameraLocked(false)
            player.isCameraLocked = false
        end
    end
    if Game:getPlatformUserId() == platformUserId then
        player:sendPacket({
            pid = "cancelSleep"
        })
    end
end

function GameListener.onPlayerDeath(userId)
    if userId ~= Game:getPlatformUserId() then
        return
    end
    local player = PlayerManager:getPlayerByUserId(userId)
    if not player then
        return
    end
    local customGame = T(Global, "customGame")
    customGame:onPlayerDeath(player)
end

GameListener:init()

return GameListener